<?php
require_once 'includes/layout.php'; require_login(); $user=current_user(); $role=$user['role']; $students=visible_students();
$count=count($students); $recorded=array_values(array_filter($students,fn($s)=>(int)$s['attendance_count']>0)); $rate=$recorded?array_sum(array_column($recorded,'attendance_rate'))/count($recorded):null; $risk=['High'=>0,'Medium'=>0,'Low'=>0]; foreach($students as $student) if($student['attendance_count']||$student['grade_count']) $risk[$student['risk_level']]++;
$scope=student_scope_sql(); $subjectScope=subject_scope_sql(); $labels=[]; $week=[];
for($i=6;$i>=0;$i--) { $date=date('Y-m-d',strtotime("-$i days")); $labels[]=date('D',strtotime($date)); $total=(int)scalar('SELECT COUNT(*) FROM attendance a JOIN students s ON s.id=a.student_id LEFT JOIN subjects sub ON sub.id=a.subject_id WHERE '.$scope.' AND '.$subjectScope.' AND a.date=?',[$date]); $present=(int)scalar('SELECT COUNT(*) FROM attendance a JOIN students s ON s.id=a.student_id LEFT JOIN subjects sub ON sub.id=a.subject_id WHERE '.$scope.' AND '.$subjectScope.' AND a.date=? AND a.status IN ("Present","Late","Excused")',[$date]); $week[]=$total?round($present/$total*100,1):null; }
$grades=rows('SELECT g.*,sub.code,u.full_name FROM grades g JOIN students s ON s.id=g.student_id JOIN users u ON u.id=s.user_id JOIN subjects sub ON sub.id=g.subject_id WHERE '.$scope.' AND '.$subjectScope.' ORDER BY g.id DESC LIMIT 8');
render_header('Academic dashboard'); ?>
<div class="page-title"><div><span class="eyebrow">ACADEMIC WORKSPACE</span><h1>Your academic overview</h1><p>Recorded information for <?= e(strtolower($role)) ?> access. Updated as attendance and grades are saved.</p></div><a class="btn btn-outline-primary" href="/portal">Campus overview →</a></div>
<div class="row g-3 mb-4"><?php card_stat(in_array($role,['Admin','Teacher'])?'Students':'Linked students',(string)$count,'fa-user-graduate','primary','Within your account access'); card_stat('Attendance',$rate!==null?number_format($rate,1).'%':'—','fa-calendar-check','success','From recorded attendance'); card_stat('Needs support',(string)($risk['High']+$risk['Medium']),'fa-heart-pulse','warning','Based on academic thresholds'); card_stat('Grade records',(string)scalar('SELECT COUNT(*) FROM grades g JOIN students s ON s.id=g.student_id LEFT JOIN subjects sub ON sub.id=g.subject_id WHERE '.$scope.' AND '.$subjectScope),'fa-book','primary','Recorded subject results'); ?></div>
<div class="row g-4"><div class="col-lg-8"><section class="panel"><h2 class="panel-title">Attendance overview <span class="small text-muted">Last 7 days</span></h2><canvas id="attendanceChart" height="110"></canvas><p class="small text-muted mt-3">Days with no attendance records are left blank.</p></section></div><div class="col-lg-4"><section class="panel"><h2 class="panel-title">Support indicators</h2><canvas id="riskChart" height="190"></canvas><p class="small text-muted mt-3">Rule-based indicators, not medical or AI diagnoses.</p></section></div></div>
<section class="panel"><h2 class="panel-title">Recent grade records <a class="small" href="modules/shared/reports.php?type=performance">Open report →</a></h2><?php if(!$grades): empty_state('No grades recorded','Grades will appear after a teacher or administrator saves them.'); else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Subject</th><th>Prelim</th><th>Midterm</th><th>Final</th><th>GPA</th><th>Result</th></tr></thead><tbody><?php foreach($grades as $grade): ?><tr><?php foreach(['full_name','code','prelim','midterm','final','gpa','remarks'] as $field): ?><td><?= e($grade[$field]) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="panel"><h2 class="panel-title">Quick actions</h2><div class="quick-links"><?php if(in_array($role,['Admin','Teacher'],true)): ?><a href="modules/teacher/attendance.php">Record attendance</a><a href="modules/teacher/grades.php">Open gradebook</a><a href="modules/shared/predictive.php">Academic insights</a><?php elseif($role==='Student'): ?><a href="modules/student/grades.php">My grades</a><a href="modules/student/attendance.php">My attendance</a><a href="modules/student/schedule.php">Class schedule</a><?php else: ?><a href="modules/parent/monitor.php">Student monitoring</a><?php endif; ?><a href="modules/shared/reports.php">Download reports</a></div></section>
<script>document.addEventListener('DOMContentLoaded',()=>{makeLineChart('attendanceChart',<?= json_encode($labels) ?>,<?= json_encode($week) ?>,'Attendance %');makeDoughnut('riskChart',<?= json_encode(array_keys($risk)) ?>,<?= json_encode(array_values($risk)) ?>);});</script>
<?php render_footer(); ?>
